      "建议活动（简略步骤）": "①拍摄完整复叶与卷须；②数一片复叶的小叶数；③记录花、幼果和黑色熟果；④每月复访同株建立物候表。⑤学习绞股蓝炒制药物流程，识别绞股蓝医学价值。",
