      "建议活动（简略步骤）": "①经种植者许可观察叶背；②核对花序与壳斗；③访谈清明至谷雨采叶经验；④把采叶、开花、果熟分别建档。⑤学习炒制甜茶过程。",
      "适用年龄/人群": "小学高年级及以上；低龄儿童由成人陪同。",
      "推荐季节及时间": "采叶文化观察以4月清明至谷雨间为重点；找花5—9月，观察上一年花形成的成熟坚果6—10月。",
      "安全注意事项": "叶味不能作为唯一鉴定依据；不自行采食；经营者安排的成品体验与野外尝食分开。"
