    "longitude": 106.3804615,
    "latitude": 29.84028,
    "summary": "蜂箱设置在屋檐下的支架上，是村民开展养蜂生产的设施，也是观察蜜蜂生活与农业联系的窗口。蜜蜂群体具有蜂王、工蜂和雄蜂等分工，工蜂在适宜天气下外出访花，采集花蜜和花粉，并参与植物授粉。参访可由养蜂者引导，在指定位置观察蜜蜂出入蜂箱的活动，记录天气、花期与访花行为，理解蜂群协作、蜜源植物和乡村生产之间的关系。",
    "photo": "https://down-files.2bulu.com/f/dn1?downParams=nIJD3kOVPYJNrROBz97TY30O9XbElguf",
