      "建议活动（简略步骤）": "①在许可边界外读牌；②画降雨—径流—产沙过程；③室内以相同坡度和水量对比有无覆盖沙盘；④比较出水浑浊和收集体积。",
      "适用年龄/人群": "建议9岁及以上；沙盘由教师操作。",
