    "summary": "小池塘位于林木和竹类环绕的环境中，人工池缘勾勒出水体边界，水面映照着周围植被。岸边遮阴、降雨补给和蒸发共同影响小水体的状态，使这里成为观察水循环与微生境的生动场所。可在安全岸段选择固定位置，连续记录水位、天气、水面变化和可见生物，认识水体与周边陆地环境的联系，并学习用水样检测了解水质指标。",
